/*---------------------------------------------------------------------------------------------
 *  SideX Terminal AI — Cmd/Ctrl+K in the integrated terminal.
 *
 *  Turns a natural-language request into a shell command and offers to insert
 *  or run it. The command is generated by the local agent server
 *  (`/v1/terminal-command`) and is never executed without the user's choice.
 *--------------------------------------------------------------------------------------------*/

import { localize2 } from '../../../../../nls.js';
import { KeyCode, KeyMod } from '../../../../../base/common/keyCodes.js';
import { KeybindingWeight } from '../../../../../platform/keybinding/common/keybindingsRegistry.js';
import { IConfigurationService } from '../../../../../platform/configuration/common/configuration.js';
import { registerTerminalAction } from '../../../terminal/browser/terminalActions.js';
import { ITerminalInstance } from '../../../terminal/browser/terminal.js';
import { OperatingSystem } from '../../../../../base/common/platform.js';
import { TerminalContextKeys } from '../../../terminal/common/terminalContextKey.js';
import { serverHttpUrl } from '../../../sidexChat/browser/localServer.js';
import { TerminalAIWidget } from './terminalAIWidget.js';
import './media/terminalAI.css';

const TERMINAL_AI_COMMAND_ID = 'workbench.action.terminal.sidexAI';

/** One widget per terminal instance; a second Cmd+K re-focuses instead of stacking. */
const widgets = new WeakMap<ITerminalInstance, TerminalAIWidget>();

function shellName(instance: ITerminalInstance): string {
	const executable = instance.shellLaunchConfig?.executable;
	if (executable) {
		return executable.split(/[\\/]/).pop() || executable;
	}
	return instance.processName || 'sh';
}

function osName(instance: ITerminalInstance): string {
	const os = instance.os;
	if (os === OperatingSystem.Windows) { return 'windows'; }
	if (os === OperatingSystem.Macintosh) { return 'macos'; }
	return 'linux';
}

function terminalContext(instance: ITerminalInstance): string {
	const selection = instance.selection;
	if (selection && selection.trim()) {
		return selection;
	}
	// No selection: take the most recent scrollback lines so the model can see
	// errors the user is reacting to. Bounded by the server as well.
	const lines: string[] = [];
	const iterator = instance.xterm?.getBufferReverseIterator();
	if (!iterator) { return ''; }
	for (let i = 0; i < 40; i++) {
		const next = iterator.next();
		if (next.done) { break; }
		lines.push(next.value);
	}
	return lines.reverse().join('\n');
}

export function openTerminalAI(instance: ITerminalInstance, configurationService: IConfigurationService): void {
	const existing = widgets.get(instance);
	if (existing) {
		existing.dispose();
		widgets.delete(instance);
	}

	let widget: TerminalAIWidget;
	widget = new TerminalAIWidget(instance.domElement, {
		onSubmit: instruction => {
			void streamCommand(instance, configurationService, instruction, widget);
		},
		onCancel: () => {
			widget.dispose();
			widgets.delete(instance);
			instance.focus();
		},
		onAccept: (command, execute) => {
			widget.dispose();
			widgets.delete(instance);
			instance.focus();
			// `runCommand` sends text to the pty; execute=false leaves it on the
			// prompt for the user to confirm, execute=true submits it.
			void instance.runCommand(command, execute);
		},
	});
	widgets.set(instance, widget);
}

async function streamCommand(
	instance: ITerminalInstance,
	configurationService: IConfigurationService,
	instruction: string,
	widget: TerminalAIWidget,
): Promise<void> {
	const httpUrl = serverHttpUrl(configurationService.getValue<string>('sidex.chat.serverUrl'));
	const model = configurationService.getValue<string>('sidex.selectedModel') || '';

	try {
		const resp = await fetch(`${httpUrl}/v1/terminal-command`, {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({
				instruction,
				cwd: instance.cwd ?? '',
				shell: shellName(instance),
				os: osName(instance),
				context: terminalContext(instance),
				model,
			}),
		});

		if (!resp.ok) {
			throw new Error(`Server error: ${resp.status}`);
		}
		const reader = resp.body?.getReader();
		if (!reader) {
			throw new Error('No response body');
		}

		const decoder = new TextDecoder();
		let buffer = '';
		while (true) {
			const { done, value } = await reader.read();
			if (done) { break; }
			buffer += decoder.decode(value, { stream: true });

			const lines = buffer.split('\n');
			buffer = lines.pop() || '';
			for (const line of lines) {
				if (!line.startsWith('data: ')) { continue; }
				const jsonStr = line.slice(6).trim();
				if (!jsonStr) { continue; }
				let chunk: { type?: string; content?: string; error?: string };
				try {
					chunk = JSON.parse(jsonStr);
				} catch (e) {
					if (e instanceof SyntaxError) { continue; }
					throw e;
				}
				if (chunk.type === 'text' && chunk.content) {
					widget.appendChunk(chunk.content);
				} else if (chunk.type === 'error') {
					throw new Error(chunk.error || 'Unknown server error');
				}
			}
		}
		widget.finish();
	} catch (err) {
		widget.setError(err instanceof Error ? err.message : String(err));
	}
}

registerTerminalAction({
	id: TERMINAL_AI_COMMAND_ID,
	title: localize2('sidexTerminalAI', 'SideX: Generate Terminal Command'),
	precondition: TerminalContextKeys.focus,
	keybinding: {
		primary: KeyMod.CtrlCmd | KeyCode.KeyK,
		// Higher than the terminal Clear action's WorkbenchContrib + 1 so this
		// wins while the terminal is focused. Clear stays available from the
		// command palette and its menu entry.
		weight: KeybindingWeight.WorkbenchContrib + 100,
		when: TerminalContextKeys.focus,
	},
	run: async (c, accessor) => {
		const instance = c.service.activeInstance;
		if (!instance) {
			return;
		}
		openTerminalAI(instance, accessor.get(IConfigurationService));
	},
});
